/* Global accent replacements; keep the original soft-orange token unchanged. */
:root {
    --_colors---background-color--orange: #d90000;
    --_colors---background-color--orange-light: #a9bdd6;
    --wds-accent-navy: #122c4e;
}
/* Preserve original orange accents in the rating and testimonial sections. */
.section.success-rating,
section[data-wds--testimonials-section--variant] {
    --_colors---background-color--orange: #ff5100;
    --_colors---background-color--orange-light: #ff933d;
}
/* Replace the hard-coded orange highlight shadow without changing its geometry. */
.measurable {
    box-shadow: inset 0 4px 14px #a9bdd680;
}
/* Navy for former light-orange primary CTAs; existing hero/final CTA red
   overrides and global red hover treatment remain in effect. */
body .primary-button[data-wds--primary-button--variant="orange-light"]:not(:is(:hover,:focus-visible)) {
    background-color: var(--wds-accent-navy);
    color: #fff;
}
