    color: #fff;
}
/* Preserve the original light-orange CTA inside the rating sections, if present. */
.section.success-rating .primary-button[data-wds--primary-button--variant="orange-light"]:not(:is(:hover,:focus-visible)),
section[data-wds--testimonials-section--variant] .primary-button[data-wds--primary-button--variant="orange-light"]:not(:is(:hover,:focus-visible)) {
    background-color: #ff933d;
    color: #0d0d0d;
