 .navbar .navbar-left-wrap{gap:.75rem}
 .navbar .wds-header-email{padding:.8rem .85rem;font-size:.875rem}
}
@media(max-width:600px){
 .navbar .wds-header-email{width:2.5rem;height:2.5rem;padding:0;display:grid;place-items:center}
 .navbar .wds-header-email .button-arrows,.navbar .wds-header-email .button-texts{display:none!important}
 .navbar .wds-header-mail-icon{display:block;position:relative;z-index:2}
 .navbar .nav-buttton-wrap{gap:.4rem}
 .navbar .nav-wrapper{gap:.4rem}
}
.section.home-hero .performance-icon{filter:url(#wds-asterisk-navy)!important}
.section.home-hero .wrapper.home-hero{width:100%;max-width:64rem;container-type:inline-size}
.section.home-hero .wds-hero-headline{width:100%;max-width:100%;margin-inline:auto;font-size:clamp(1rem,6vw,5.375rem);font-size:clamp(1rem,8.2cqi,5.375rem);line-height:1.04;letter-spacing:-.045em}
.wds-hero-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.wds-hero-fixed,.wds-hero-audience{display:block;white-space:nowrap;text-align:center}
.wds-hero-word-stack{display:grid;grid-template-columns:minmax(0,1fr);width:100%;text-align:center;align-items:baseline;isolation:isolate}
.wds-hero-word{grid-area:1/1;visibility:hidden;opacity:0;transform:translateY(.22em);white-space:nowrap;color:#0d0d0d;transition:opacity .28s ease,transform .4s cubic-bezier(.2,.7,.25,1),visibility 0s linear .4s}
.wds-hero-word.is-active{visibility:visible;opacity:1;transform:translateY(0);transition:opacity .32s ease,transform .4s cubic-bezier(.2,.7,.25,1),visibility 0s}
@media(prefers-reduced-motion:reduce){.wds-hero-word{transition:none!important;transform:none!important}}


/* Fixed floating header, with its original position reserved in the document. */
.wds-sticky-header-space{height:var(--wds-header-space,5rem);min-height:0}
.wds-sticky-header-space>.navbar.w-nav{position:fixed!important;top:var(--_sizes---spacing--spacing-medium,1.25rem);left:1rem;right:1rem;width:calc(100% - 2rem);max-width:75rem;margin:0 auto;z-index:1100}
html{scroll-padding-top:calc(var(--wds-header-space,5rem) + .75rem)}
.wds-sticky-header-space>.navbar.w-nav.w--open{z-index:1101}
/* Soft white masonry, isolated behind the original hero content. */
.section.home-hero{position:relative;isolation:isolate;overflow:hidden;background:#fff}
.section.home-hero>.container{position:relative;z-index:1}
.wds-hero-brick-field{position:absolute;inset:0;z-index:0;overflow:hidden;pointer-events:none;background:#f8f9fa;perspective:1000px;mask-image:linear-gradient(to bottom,transparent 0%,#000 24%,#000 76%,transparent 100%);-webkit-mask-image:linear-gradient(to bottom,transparent 0%,#000 24%,#000 76%,transparent 100%)}
.wds-hero-brick-field:empty{background:none}
.wds-hero-brick-field::after{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at center,#ffffff38 0%,#ffffff18 50%,transparent 85%);pointer-events:none;z-index:2}
.wds-hero-brick{position:absolute;box-sizing:border-box;width:var(--brick-w);height:var(--brick-h);border:1px solid #e9ecf0;border-radius:7px;background:linear-gradient(145deg,#fff 15%,#fdfdfe 85%);box-shadow:0 1px 1px #122c4e06;transform:translate3d(0,0,0);transform-origin:center;transition:transform .5s cubic-bezier(.2,.7,.25,1),box-shadow .4s ease}
.wds-hero-brick.is-raised{z-index:1;transform:translate3d(0,var(--brick-lift),var(--brick-depth)) rotateX(var(--brick-rx)) rotateY(var(--brick-ry));box-shadow:0 2px 0 #e8ebee,0 5px 12px #122c4e0d;transition-duration:.2s,.25s}
@media(max-width:767px){.wds-hero-brick-field{opacity:.6}.wds-hero-brick-field::after{background:radial-gradient(ellipse at center,#ffffff38,transparent 85%)}}
@media(prefers-reduced-motion:reduce){.wds-hero-brick,.wds-hero-brick.is-raised{transform:none!important;transition:none!important;box-shadow:0 1px 1px #122c4e06}}
